package prometheus

import (
	"bytes"
	"fmt"
	"slices"
	"strings"

	"go.yaml.in/yaml/v3"

	"github.com/abhinavcdev/sloeval/internal/ir"
)

// Header starts every generated file.
const Header = "# Code generated by sloe from an AISLO spec. DO NOT EDIT.\n"

type ruleFile struct {
	Groups []ruleGroup `yaml:"groups"`
}

type ruleGroup struct {
	Name     string `yaml:"name"`
	Interval string `yaml:"interval,omitempty"`
	Rules    []rule `yaml:"rules"`
}

type rule struct {
	Record      string            `yaml:"record,omitempty"`
	Alert       string            `yaml:"alert,omitempty"`
	Expr        string            `yaml:"expr"`
	Labels      map[string]string `yaml:"labels,omitempty"`
	Annotations map[string]string `yaml:"annotations,omitempty"`
}

// Rules renders the rule file for one spec.
func Rules(s *ir.Spec, opt Options) ([]byte, error) {
	n := opt.naming()
	var f ruleFile
	for i := range s.SLOs {
		slo := &s.SLOs[i]
		labels := slo.SeriesLabels()

		sli := ruleGroup{Name: "sloe:" + slo.ID + ":sli"}
		for _, w := range slo.RateWindows {
			sli.Rules = append(sli.Rules, rule{
				Record: RecordErrorRatio + window(w),
				Expr:   ErrorRatioExpr(slo.SLI, w, n),
				Labels: labels,
			})
		}

		meta := ruleGroup{Name: "sloe:" + slo.ID + ":meta", Interval: "1m"}
		full := RecordErrorRatio + window(slo.Window)
		if !slices.Contains(slo.RateWindows, slo.Window) {
			meta.Rules = append(meta.Rules, rule{
				Record: full,
				Expr:   fmt.Sprintf("avg_over_time(%s[%s])", idSelector(RecordErrorRatio+"5m", slo), window(slo.Window)),
				Labels: labels,
			})
		}
		budget := ir.FormatFloat(slo.Budget)
		info := cloneWith(labels, map[string]string{
			ir.LabelSLIKind:   slo.SLI.Kind,
			ir.LabelObjective: ir.FormatFloat(slo.Objective * 100),
		})
		meta.Rules = append(meta.Rules,
			rule{Record: RecordObjective, Expr: "vector(" + ir.FormatFloat(slo.Objective) + ")", Labels: labels},
			rule{Record: RecordBudget, Expr: "vector(" + budget + ")", Labels: labels},
			rule{Record: RecordBudgetRemaining, Expr: fmt.Sprintf("1 - (%s / %s)", idSelector(full, slo), budget), Labels: labels},
			rule{Record: RecordBurnRate + "5m", Expr: fmt.Sprintf("%s / %s", idSelector(RecordErrorRatio+"5m", slo), budget), Labels: labels},
			rule{Record: RecordBurnRate + "1h", Expr: fmt.Sprintf("%s / %s", idSelector(RecordErrorRatio+"1h", slo), budget), Labels: labels},
			rule{Record: RecordInfo, Expr: "vector(1)", Labels: info},
		)

		f.Groups = append(f.Groups, sli, meta)
		if len(slo.Alerts) > 0 {
			alerts := ruleGroup{Name: "sloe:" + slo.ID + ":alerts"}
			for _, a := range slo.Alerts {
				alerts.Rules = append(alerts.Rules, rule{
					Alert:       a.Name,
					Expr:        AlertExpr(slo, a),
					Labels:      a.Labels,
					Annotations: a.Annotations,
				})
			}
			f.Groups = append(f.Groups, alerts)
		}
	}
	return marshal(f)
}

// AlertExpr renders the multi-window multi-burn-rate condition of an alert.
func AlertExpr(slo *ir.SLO, a ir.Alert) string {
	parts := make([]string, len(a.Windows))
	budget := ir.FormatFloat(slo.Budget)
	for i, w := range a.Windows {
		thr := "(" + ir.FormatFloat(w.BurnRate) + " * " + budget + ")"
		parts[i] = fmt.Sprintf("(%s > %s and %s > %s)",
			idSelector(RecordErrorRatio+window(w.Long), slo), thr,
			idSelector(RecordErrorRatio+window(w.Short), slo), thr)
	}
	return strings.Join(parts, "\nor\n")
}

func cloneWith(m, extra map[string]string) map[string]string {
	out := make(map[string]string, len(m)+len(extra))
	for k, v := range m {
		out[k] = v
	}
	for k, v := range extra {
		out[k] = v
	}
	return out
}

func marshal(v any) ([]byte, error) {
	var buf bytes.Buffer
	buf.WriteString(Header)
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(v); err != nil {
		return nil, err
	}
	if err := enc.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}
